parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "category": {
      "type": "string",
      "description": "Genau 'User Story' für Feature-Wünsche/Verbesserungen aus Nutzersicht, oder 'Technical Task' für technische Aufgaben/Bugs/Code-Änderungen.",
      "enum": [
        "User Story",
        "Technical Task"
      ]
    },
    "priority": {
      "type": "string",
      "description": "'urgent' bei Wörtern wie dringend/asap/kritisch, sonst 'medium' oder 'low' je nach Tonfall.",
      "enum": [
        "urgent",
        "medium",
        "low"
      ]
    },
    "deadline": {
      "type": "string",
      "description": "Explizite Frist als YYYY-MM-DD. Relative Angaben anhand des Referenzdatums auflösen. Ohne eindeutige Frist leerer String. Keine Frist erfinden."
    },
    "salutation": {
      "type": "string",
      "description": "Nur explizite Selbstbezeichnung Herr oder Frau übernehmen; sonst unbekannt. Nicht aus Namen erraten.",
      "enum": [
        "Herr",
        "Frau",
        "unbekannt"
      ]
    },
    "description": {
      "type": "string",
      "description": "Beschreibung im Originalwortlaut, ohne Zusammenfassung. Explizite Zuweisungen, Fristangaben und separate Aufgabenlisten entfernen; übrigen Text unverändert erhalten."
    },
    "subtask": {
      "type": "array",
      "description": "Zerlege die Aufgabe eigenständig in 2-4 kurze, konkrete Arbeitsschritte, auch wenn keine explizite Liste im Text steht.",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": "number"
          },
          "value": {
            "type": "string"
          },
          "edit": {
            "type": "boolean"
          },
          "checked": {
            "type": "boolean"
          }
        },
        "required": [
          "id",
          "value",
          "edit",
          "checked"
        ]
      }
    },
    "assigned": {
      "type": "array",
      "description": "Nur ausdrücklich zuständige Personen. Namen unverändert übernehmen. E-Mail nur falls explizit vorhanden, sonst leerer String. Keine Adressen erfinden. Sonst leeres Array.",
      "items": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string"
          },
          "email": {
            "type": "string"
          }
        },
        "required": [
          "name",
          "email"
        ]
      }
    },
    "title": {
      "type": "string",
      "description": "Kurzer, konkreter Aufgabentitel auf Deutsch, möglichst maximal 60 Zeichen; Umlaute erhalten."
    }
  },
  "required": [
    "category",
    "priority",
    "deadline",
    "salutation",
    "description",
    "subtask",
    "assigned",
    "title"
  ]
}
